// LAB: Enforce an admission budget
// Create a gate with a maximum active count. Admit only below the limit, release one existing permit at a time, and reject a release when none is held.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>

int main() {
    const unsigned budget_mib = 64;
    const unsigned per_connection_mib = 2;
    const unsigned limit = budget_mib / per_connection_mib;
    const unsigned active = 32;
    std::cout << "limit=" << limit << " admit=" << std::boolalpha
              << (active < limit) << '\n';
    assert(limit == 32 && !(active < limit));
}

solutions.code:
#include <cassert>
#include <iostream>
#include <mutex>

class Gate {
    unsigned active_ = 0;
    const unsigned limit_;
    std::mutex mutex_;
public:
    explicit Gate(unsigned limit) : limit_(limit) {}
    bool admit() {
        std::lock_guard<std::mutex> lock(mutex_);
        if(active_ == limit_) return false;
        ++active_; return true;
    }
    bool release() {
        std::lock_guard<std::mutex> lock(mutex_);
        if(active_ == 0) return false;
        --active_; return true;
    }
};

int main() {
    Gate gate(2);
    assert(gate.admit() && gate.admit() && !gate.admit());
    assert(gate.release() && gate.admit());
    assert(gate.release() && gate.release() && !gate.release());
    Gate closed(0); assert(!closed.admit());
    std::cout << "limit=2 third=rejected released=reusable\n";
}

